    )
    case CryptoError(String
    )
    case SerializationError(String
    )
    case InvalidArgument(String
    )
    case IoError(String
    )
    case InvalidData(String
    )
    case StaleFiles(missingPaths: [String]
    )
    case CorruptedImagePayload
    case DecryptionFailed
    case SyncTransportError(String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeNookClipError: FfiConverterRustBuffer {
    typealias SwiftType = NookClipError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> NookClipError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .DatabaseError(
            try FfiConverterString.read(from: &buf)
            )
        case 2: return .NotFound(
            try FfiConverterString.read(from: &buf)
            )
        case 3: return .CryptoError(
            try FfiConverterString.read(from: &buf)
            )
        case 4: return .SerializationError(
            try FfiConverterString.read(from: &buf)
            )
        case 5: return .InvalidArgument(
            try FfiConverterString.read(from: &buf)
            )
        case 6: return .IoError(
            try FfiConverterString.read(from: &buf)
            )
        case 7: return .InvalidData(
            try FfiConverterString.read(from: &buf)
            )
        case 8: return .StaleFiles(
            missingPaths: try FfiConverterSequenceString.read(from: &buf)
            )
        case 9: return .CorruptedImagePayload
        case 10: return .DecryptionFailed
        case 11: return .SyncTransportError(
            try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: NookClipError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .DatabaseError(v1):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .NotFound(v1):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .CryptoError(v1):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .SerializationError(v1):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .InvalidArgument(v1):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .IoError(v1):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .InvalidData(v1):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .StaleFiles(missingPaths):
            writeInt(&buf, Int32(8))
            FfiConverterSequenceString.write(missingPaths, into: &buf)
            
        
        case .CorruptedImagePayload:
            writeInt(&buf, Int32(9))
        
        
        case .DecryptionFailed:
            writeInt(&buf, Int32(10))
        
        
        case let .SyncTransportError(v1):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(v1, into: &buf)
            
        }
    }
}


